import React,{useState} from 'react';import{createRoot}from'react-dom/client';import{AgentLounge}from '../../../app/components/agent-lounge';import '../../../app/components/agent-lounge.css';import type{LoungeMode}from '../../../lib/lounge-contract';
const names=['atlas','forge','frame','palette','scout','sentinel'] as const;
function App(){const [paused,setPaused]=useState(false);const [selected,setSelected]=useState('demo-one');const [opened,setOpened]=useState('');const [mode,setMode]=useState<LoungeMode>('completed');const [attempt,setAttempt]=useState('attempt-one');const [shown,setShown]=useState(true);const [pct,setPct]=useState(30);const [tick,setTick]=useState(0);Object.assign(window,{demo:{setMode,setAttempt,setShown,setPct,poll:()=>setTick(x=>x+1)}});return <><AgentLounge roles={names.map((role,i)=>({role,mode:i===0&&shown?mode:i===1?'blocked':'idle',task:i===0&&shown?{id:selected} as any:null,attemptId:i===0&&shown?attempt:null,verifiedPct:i===0&&shown?pct:null,candidateTaskIds:i===0&&shown?['demo-one','demo-two']:[],statusLabel:i===0&&shown?mode:i===1?'차단됨':'휴식 중',completionKey:i===0&&shown&&mode==='completed'?`${selected}:${attempt}`:null}))} motionPaused={paused} onMotionPausedChange={setPaused} onSelectTask={(_,id)=>setSelected(id)} onOpenTask={setOpened}/><output>{opened}</output><span hidden>{tick}</span></>};createRoot(document.getElementById('root')!).render(<App/>);
